//! Black-box regression suite for XZ and LZMA: `.xz` files, `.tar.xz`, and
//! ZIP methods 14 (LZMA) and 95 (XZ).
//!
//! Every fixture is an embedded byte array produced once by `xz` 5.8,
//! python3 (`tarfile`, `zipfile`) and `7zz`; nothing here needs external
//! tools. Expected contents are regenerated by the helpers below.
#![cfg(feature = "full")]

use std::io::{Cursor, Write};

use unretro::{ContainerFormat, EntryType, Loader, VisitAction, detect_format};

type Listing = Vec<(String, Vec<u8>)>;

/// Leaves at any depth, sorted by path, with the traversal diagnostics.
fn leaves_and_diagnostics(data: &[u8], name: &str) -> Result<(Listing, Vec<String>), String> {
    let mut entries = Listing::new();
    let report = Loader::from_bytes(data.to_vec(), name)
        .visit_with_report(EntryType::Leaves, |entry| {
            entries.push((entry.path.to_string(), entry.data.to_vec()));
            Ok(VisitAction::Continue)
        })
        .map_err(|e| e.to_string())?;
    entries.sort();
    let diagnostics = report
        .diagnostics
        .iter()
        .map(|diagnostic| diagnostic.message.clone())
        .collect();
    Ok((entries, diagnostics))
}

/// Leaves at any depth, sorted by path. Any traversal diagnostic is an error.
fn leaves(data: &[u8], name: &str) -> Result<Listing, String> {
    let (entries, diagnostics) = leaves_and_diagnostics(data, name)?;
    match diagnostics.into_iter().next() {
        Some(message) => Err(message),
        None => Ok(entries),
    }
}

#[track_caller]
fn assert_leaves(data: &[u8], name: &str, expected: &[(&str, &[u8])]) {
    let listing = leaves(data, name).unwrap_or_else(|e| panic!("{name} rejected: {e}"));
    let mut expected: Vec<(&str, &[u8])> = expected.to_vec();
    expected.sort();
    let got: Vec<&str> = listing.iter().map(|(path, _)| path.as_str()).collect();
    let want: Vec<&str> = expected.iter().map(|(path, _)| *path).collect();
    assert_eq!(got, want, "entry paths of {name}");
    for ((path, data), (_, want)) in listing.iter().zip(&expected) {
        assert_eq!(data.len(), want.len(), "size of {path}");
        assert!(data == want, "content of {path} differs");
    }
}

/// The message the input is rejected with; panics when it is accepted.
#[track_caller]
fn rejection(data: &[u8], name: &str) -> String {
    match leaves(data, name) {
        Ok(listing) => {
            let paths: Vec<&str> = listing.iter().map(|(path, _)| path.as_str()).collect();
            panic!("corrupt {name} was accepted: {paths:?}");
        }
        Err(message) => message,
    }
}

#[track_caller]
fn assert_rejected(data: &[u8], name: &str) {
    rejection(data, name);
}

const TEXT: &[u8] = b"It was the best of times, it was the worst of times, it was the age of wisdom, it was the age of foolishness, it was the epoch of belief, it was the epoch of incredulity.\n";

/// Compressible data that spans three blocks of 16384 bytes.
fn pattern() -> Vec<u8> {
    (0..40_000u64).map(|i| ((i * i) % 31) as u8).collect()
}

/// 32-bit little-endian counters, the shape the Delta filter is made for.
fn ramp() -> Vec<u8> {
    (0..4000u32).flat_map(|i| (i * 3).to_le_bytes()).collect()
}

/// Incompressible bytes (xorshift64), stored by LZMA2 as an uncompressed chunk.
fn noise() -> Vec<u8> {
    let mut x: u64 = 0x2545_F491_4F6C_DD1D;
    (0..300)
        .map(|_| {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            (x >> 32) as u8
        })
        .collect()
}

fn long_name() -> String {
    format!("dir/{}.txt", "n".repeat(120))
}

