#[test]
fn xz_file_with_each_check_type_yields_one_entry_named_after_the_file() {
    for data in [XZ_NONE, XZ_CRC32, XZ_CRC64, XZ_SHA256] {
        assert_leaves(data, "t.txt.xz", &[("t.txt.xz/t.txt", TEXT)]);
    }
    assert_leaves(XZ_CRC64, "T.TXT.XZ", &[("T.TXT.XZ/T.TXT", TEXT)]);
    assert_leaves(XZ_EMPTY, "e.bin.xz", &[("e.bin.xz/e.bin", b"")]);

    let info = Loader::from_bytes(XZ_CRC64.to_vec(), "t.txt.xz")
        .info()
        .unwrap();
    assert_eq!(info.format, ContainerFormat::Xz);
}

#[test]
fn multiple_blocks_filters_and_chunk_types_decode_exactly() {
    assert_leaves(XZ_BLOCKS, "p.bin.xz", &[("p.bin.xz/p.bin", &pattern())]);
    assert_leaves(XZ_DELTA, "r.bin.xz", &[("r.bin.xz/r.bin", &ramp())]);
    assert_leaves(XZ_NOISE, "n.bin.xz", &[("n.bin.xz/n.bin", &noise())]);
    assert_leaves(XZ_PROPS, "p.bin.xz", &[("p.bin.xz/p.bin", &pattern())]);
}

#[test]
fn concatenated_streams_and_stream_padding_decode_as_one_file() {
    let doubled = [TEXT, TEXT].concat();
    let two = [XZ_CRC32, XZ_SHA256].concat();
    assert_leaves(&two, "t.txt.xz", &[("t.txt.xz/t.txt", &doubled)]);

    // Padding is a multiple of four zero bytes between or after streams.
    let padded = [XZ_CRC32, &[0; 8], XZ_SHA256, XZ_EMPTY, &[0; 4]].concat();
    assert_leaves(&padded, "t.txt.xz", &[("t.txt.xz/t.txt", &doubled)]);

    let mut expected = pattern();
    expected.extend_from_slice(TEXT);
    let mixed = [XZ_EMPTY, XZ_BLOCKS, XZ_EMPTY, XZ_NONE].concat();
    assert_leaves(&mixed, "m.xz", &[("m.xz/m", &expected)]);
}

#[test]
fn bytes_after_a_stream_that_are_not_padding_reject_the_file() {
    for tail in [
        &b"\0"[..],
        b"\0\0\0",
        b"\0\0\0\0\0",
        b"junk",
        b"\0\0\0\0junk",
    ] {
        assert_rejected(&[XZ_CRC64, tail].concat(), "t.txt.xz");
    }
    // Misaligned padding between two otherwise valid streams.
    assert_rejected(&[XZ_CRC64, &[0; 2], XZ_CRC32].concat(), "t.txt.xz");
    // A second stream that stops after its header.
    assert_rejected(&[XZ_CRC64, &XZ_CRC32[..12]].concat(), "t.txt.xz");
}

#[test]
fn xz_is_detected_by_content_whatever_the_name() {
    for name in [
        "noext", "t.bin", "t.zip", "t.gz", "t.tar", "t.lzma", "t.dmg",
    ] {
        assert_eq!(
            detect_format(name, Some(XZ_CRC64)),
            Some(ContainerFormat::Xz),
            "{name}"
        );
        assert_eq!(leaves(XZ_CRC64, name).unwrap()[0].1, TEXT, "{name}");
    }
    assert_leaves(XZ_CRC64, "noext", &[("noext/noext", TEXT)]);
    assert_leaves(XZ_CRC64, "t.zip", &[("t.zip/t", TEXT)]);
    assert_eq!(
        detect_format("e", Some(XZ_EMPTY)),
        Some(ContainerFormat::Xz)
    );
    // The magic alone decides; what follows is checked when decoding.
    assert_ne!(
        detect_format("t.xz", Some(&XZ_CRC64[1..])),
        Some(ContainerFormat::Xz)
    );
}

fn tar_listing(root: &str) -> Listing {
    vec![
        (format!("{root}/hello.txt"), b"hello\n".to_vec()),
        (format!("{root}/{}", long_name()), TEXT.to_vec()),
        (format!("{root}/dir/empty"), Vec::new()),
    ]
}

fn borrowed(listing: &Listing) -> Vec<(&str, &[u8])> {
    listing
        .iter()
        .map(|(path, data)| (path.as_str(), data.as_slice()))
        .collect()
}

#[track_caller]
fn assert_tar(data: &[u8], name: &str, root: &str) {
    assert_leaves(data, name, &borrowed(&tar_listing(root)));
}

#[test]
fn tar_xz_lists_the_files_of_the_inner_tar() {
    assert_tar(TAR_XZ, "a.tar.xz", "a.tar.xz/a.tar");
    assert_tar(TAR_XZ, "a.txz", "a.txz/a.tar");
    assert_tar(TAR_XZ, "A.TXZ", "A.TXZ/A.tar");
    // Without any hint in the name the payload is still recognized as TAR.
    assert_tar(TAR_XZ, "archive", "archive/archive");

    // The tar may continue in further streams.
    let split = [TAR_XZ, XZ_EMPTY].concat();
    assert_tar(&split, "a.tar.xz", "a.tar.xz/a.tar");
}

#[test]
fn xz_nested_in_zip_and_tar_is_opened() {
    let mut zip = zip::ZipWriter::new(Cursor::new(Vec::new()));
    let stored =
        zip::write::SimpleFileOptions::default().compression_method(zip::CompressionMethod::Stored);
    zip.start_file("inner.txt.xz", stored).unwrap();
    zip.write_all(XZ_SHA256).unwrap();
    zip.start_file("sub/a.txz", stored).unwrap();
    zip.write_all(TAR_XZ).unwrap();
    let zip = zip.finish().unwrap().into_inner();
    let mut expected = tar_listing("n.zip/sub/a.txz/a.tar");
    expected.push(("n.zip/inner.txt.xz/inner.txt".to_string(), TEXT.to_vec()));
    assert_leaves(&zip, "n.zip", &borrowed(&expected));

    let mut tar = tar::Builder::new(Vec::new());
    for (name, data) in [("inner.txt.xz", XZ_CRC32), ("sub/a.tar.xz", TAR_XZ)] {
        let mut header = tar::Header::new_gnu();
        header.set_size(data.len() as u64);
        header.set_mode(0o644);
        tar.append_data(&mut header, name, data).unwrap();
    }
    let tar = tar.into_inner().unwrap();
    let mut expected = tar_listing("n.tar/sub/a.tar.xz/a.tar");
    expected.push(("n.tar/inner.txt.xz/inner.txt".to_string(), TEXT.to_vec()));
    assert_leaves(&tar, "n.tar", &borrowed(&expected));
}

#[test]
fn zip_methods_14_and_95_are_extracted_next_to_the_other_methods() {
    assert_leaves(
        ZIP_PYTHON,
        "t.zip",
        &[
            ("t.zip/stored.txt", TEXT),
            ("t.zip/deflate.txt", TEXT),
            ("t.zip/bzip2.txt", TEXT),
            ("t.zip/lzma.txt", TEXT),
            ("t.zip/empty", b""),
        ],
    );
    let pattern = pattern();
    assert_leaves(
        ZIP_7Z,
        "t.zip",
        &[("t.zip/lzma.bin", &pattern), ("t.zip/xz.bin", &pattern)],
    );
}

// Header offsets in `ZIP_7Z`.
const ZIP_LOCAL_LZMA: usize = 0;
const ZIP_LOCAL_XZ: usize = 147;
const ZIP_CENTRAL_LZMA: usize = 343;
const ZIP_CENTRAL_XZ: usize = 433;
const ZIP_FLAGS: usize = 6;
const ZIP_METHOD: usize = 8;
const ZIP_SIZE: usize = 22;

/// `ZIP_7Z` with `bytes` written at `offset` in a local header and at the
/// matching place of the central record of the same entry.
fn zip_with_field(local: usize, central: usize, offset: usize, bytes: &[u8]) -> Vec<u8> {
    let mut zip = ZIP_7Z.to_vec();
    assert_eq!(&zip[local..local + 4], b"PK\x03\x04");
    assert_eq!(&zip[central..central + 4], b"PK\x01\x02");
    zip[local + offset..local + offset + bytes.len()].copy_from_slice(bytes);
    // Central records carry two more bytes (version made by) before the same fields.
    zip[central + offset + 2..central + offset + 2 + bytes.len()].copy_from_slice(bytes);
    zip
}

fn zip_data_start(local: usize) -> usize {
    let field = |at: usize| usize::from(u16::from_le_bytes([ZIP_7Z[at], ZIP_7Z[at + 1]]));
    local + 30 + field(local + 26) + field(local + 28)
}

/// Asserts that exactly the entry `intact` of `ZIP_7Z` survives, with its
/// content, and that the loss of the other one is reported.
#[track_caller]
fn assert_only(zip: &[u8], intact: &str) {
    let (listing, diagnostics) = leaves_and_diagnostics(zip, "t.zip").unwrap();
    let paths: Vec<&str> = listing.iter().map(|(path, _)| path.as_str()).collect();
    assert_eq!(paths, [intact]);
    assert!(listing[0].1 == pattern(), "{intact} delivered damaged");
    assert_eq!(diagnostics.len(), 1, "{diagnostics:?}");
}

#[test]
fn corrupt_zip_lzma_and_xz_entries_are_skipped_not_delivered() {
    assert_eq!(ZIP_7Z[ZIP_LOCAL_LZMA + ZIP_METHOD], 14);
    assert_eq!(ZIP_7Z[ZIP_LOCAL_XZ + ZIP_METHOD], 95);
    let (lzma, xz) = ("t.zip/lzma.bin", "t.zip/xz.bin");

    // A payload bit flip in each entry.
    let mut zip = ZIP_7Z.to_vec();
    zip[zip_data_start(ZIP_LOCAL_LZMA) + 40] ^= 0x10;
    assert_only(&zip, xz);
    let mut zip = ZIP_7Z.to_vec();
    zip[zip_data_start(ZIP_LOCAL_XZ) + 40] ^= 0x10;
    assert_only(&zip, lzma);

    // Flag bit 1 promises an end marker that this stream does not have.
    let zip = zip_with_field(ZIP_LOCAL_LZMA, ZIP_CENTRAL_LZMA, ZIP_FLAGS, &[2, 0]);
    assert_only(&zip, xz);

    // An LZMA properties header of four bytes instead of five.
    let mut zip = ZIP_7Z.to_vec();
    zip[zip_data_start(ZIP_LOCAL_LZMA) + 2] = 4;
    assert_only(&zip, xz);

    // Declared sizes one byte short, one byte long and far too long.
    for size in [39_999u32, 40_001, 0xFFFF_FFF0] {
        let size = size.to_le_bytes();
        let zip = zip_with_field(ZIP_LOCAL_LZMA, ZIP_CENTRAL_LZMA, ZIP_SIZE, &size);
        assert_only(&zip, xz);
        let zip = zip_with_field(ZIP_LOCAL_XZ, ZIP_CENTRAL_XZ, ZIP_SIZE, &size);
        assert_only(&zip, lzma);
    }

    // Each method's data under the other method's number.
    let zip = zip_with_field(ZIP_LOCAL_LZMA, ZIP_CENTRAL_LZMA, ZIP_METHOD, &[95, 0]);
    assert_only(&zip, xz);
    let zip = zip_with_field(ZIP_LOCAL_XZ, ZIP_CENTRAL_XZ, ZIP_METHOD, &[14, 0]);
    assert_only(&zip, lzma);
}

#[test]
fn bcj_filters_and_reserved_checks_are_rejected_as_unsupported() {
    let message = rejection(XZ_BCJ, "t.txt.xz");
    assert!(message.contains("not supported"), "{message}");
    assert!(message.contains("BCJ"), "{message}");

    let message = rejection(XZ_RESERVED_CHECK, "r.xz");
    assert!(message.contains("not supported"), "{message}");
}

#[test]
fn every_truncation_of_an_xz_file_is_rejected() {
    for data in [XZ_NONE, XZ_CRC32, XZ_CRC64, XZ_SHA256, XZ_BLOCKS, XZ_DELTA] {
        for len in 0..data.len() {
            if let Ok(listing) = leaves(&data[..len], "t.xz") {
                panic!(
                    "accepted when cut to {len} bytes: {} entries",
                    listing.len()
                );
            }
        }
    }
}

#[test]
fn single_bit_damage_never_changes_the_output() {
    let (pattern, ramp, noise) = (pattern(), ramp(), noise());
    let files: [(&[u8], &[u8]); 6] = [
        (XZ_CRC32, TEXT),
        (XZ_CRC64, TEXT),
        (XZ_SHA256, TEXT),
        (XZ_BLOCKS, &pattern),
        (XZ_DELTA, &ramp),
        (XZ_NOISE, &noise),
    ];
    for (data, original) in files {
        let mut accepted = 0;
        for position in 0..data.len() {
            for bit in 0..8 {
                let mut damaged = data.to_vec();
                damaged[position] ^= 1 << bit;
                // A flip may survive only where it cannot alter the data: `lc`
                // in an LZMA2 properties byte when no byte has high bits set.
                if let Ok(listing) = leaves(&damaged, "t.xz") {
                    assert_eq!(listing.len(), 1);
                    assert!(
                        listing[0].1 == original,
                        "bit {bit} of byte {position} flipped and wrong data was delivered"
                    );
                    accepted += 1;
                }
            }
        }
        assert!(accepted <= 3, "{accepted} flips went unnoticed");
    }
}

#[test]
fn single_bit_damage_without_a_check_never_passes_as_the_original() {
    // With check type None only the headers, the index and the LZMA2
    // framing protect the data: a flip is either caught or changes the output.
    for position in 0..XZ_NONE.len() {
        for bit in 0..8 {
            let mut damaged = XZ_NONE.to_vec();
            damaged[position] ^= 1 << bit;
            if let Ok(listing) = leaves(&damaged, "t.xz") {
                assert_eq!(listing.len(), 1);
                assert!(
                    listing[0].1 != TEXT,
                    "bit {bit} of byte {position} flipped without any effect"
                );
            }
        }
    }
}

#[test]
fn damage_in_a_later_stream_or_block_rejects_the_whole_file() {
    let mut two = [XZ_CRC32, XZ_SHA256].concat();
    let last = two.len() - 40;
    two[last] ^= 0x01;
    assert_rejected(&two, "t.txt.xz");

    // The check of the last of three blocks sits right before the index.
    let mut blocks = XZ_BLOCKS.to_vec();
    let position = blocks.len() - 12 - 20;
    blocks[position] ^= 0x80;
    assert_rejected(&blocks, "p.bin.xz");

    let mut tar = TAR_XZ.to_vec();
    tar[100] ^= 0x04;
    assert_rejected(&tar, "a.tar.xz");
}

// TEXT from `xz --format=lzma`.
const LZMA_TEXT: &[u8] = b"\
    \x5d\x00\x00\x80\x00\xff\xff\xff\xff\xff\xff\xff\xff\x00\x24\x9d\x00\x07\x73\x43\
    \x85\x19\xc1\xbc\x61\x9e\x16\x43\x3f\x49\xa5\x27\x15\xb4\xf5\x10\x18\x54\xbf\xcd\
    \x91\x38\x3b\x33\x8b\x52\x7d\x4a\xe7\x72\xd2\xb1\xd8\x4a\x2a\x51\x00\x44\xb2\xe1\
    \x69\x9f\x12\x41\xf5\x50\xc0\x17\xd2\xce\x1a\x3a\x9f\x62\xc6\x09\xc3\x2e\x6c\xe2\
    \x1f\x67\x74\xd6\x0a\x2e\x16\x11\x35\xc1\xc4\xb2\x72\x93\x6d\x5e\xde\x71\x9c\xf8\
    \x7f\xff\xfe\x58\x45\x40";

#[test]
fn legacy_lzma_file_is_opened_under_its_extension() {
    assert_leaves(LZMA_TEXT, "t.txt.lzma", &[("t.txt.lzma/t.txt", TEXT)]);
    assert_leaves(LZMA_TEXT, "T.LZMA", &[("T.LZMA/T", TEXT)]);
    assert_eq!(
        detect_format("t.lzma", Some(LZMA_TEXT)),
        Some(ContainerFormat::Xz)
    );
    // The format has no magic, so no other name selects it.
    for name in ["t", "t.xz", "t.bin"] {
        assert_eq!(detect_format(name, Some(LZMA_TEXT)), None, "{name}");
    }

    let mut zip = zip::ZipWriter::new(Cursor::new(Vec::new()));
    let stored =
        zip::write::SimpleFileOptions::default().compression_method(zip::CompressionMethod::Stored);
    zip.start_file("sub/inner.txt.lzma", stored).unwrap();
    zip.write_all(LZMA_TEXT).unwrap();
    let zip = zip.finish().unwrap().into_inner();
    assert_leaves(
        &zip,
        "n.zip",
        &[("n.zip/sub/inner.txt.lzma/inner.txt", TEXT)],
    );
}

#[test]
fn damaged_legacy_lzma_file_is_rejected() {
    // As the `xz` tool does, also for bytes after the end marker.
    for extra in [&b"junk"[..], &[0u8; 4], LZMA_TEXT] {
        let message = rejection(&[LZMA_TEXT, extra].concat(), "t.lzma");
        assert!(message.contains("lzma"), "{message}");
    }
    for len in 18..LZMA_TEXT.len() {
        assert_rejected(&LZMA_TEXT[..len], "t.lzma");
    }
}
